//! Generate files of the web components from Rust, e.g. the colors of the theme as CSS and
//! TypeScript and the shaders in GLSL, so that they are defined only once in the workspace.
//!
//! The copyright notices of the generated files are the ones of [`crate::generated`].

use std::error::Error;
use std::path::Path;

use mu::viewer::shaders::{ModelWeb, Shader, ShaderSource, UniformBlock, WEB_SHADERS};
use mu::viewer::{Lighting, Theme};
use mucad_driver::prelude as mu;

use crate::generated::Generated;

/// The directory of the generated files, relative to the workspace root.
const GENERATED_DIR: &str = "editors/web-components/src/generated";

/// The source of the generated theme files.
const THEME_SOURCE: &str = "`Theme::default()` of `mucad-viewer-utils`";

/// The note of a generated file, which says where it comes from, e.g. [`THEME_SOURCE`].
fn note(source: &str) -> String {
    format!("Generated by `cargo xtask web` from {source}, do not edit.")
}

/// Write the generated files, or with `check` only report the ones which are outdated.
pub fn web(check: bool) -> Result<(), Box<dyn Error>> {
    crate::generated::write(generated_files()?, check, "cargo xtask web")
}

/// The generated files.
fn generated_files() -> Result<Vec<Generated>, Box<dyn Error>> {
    let theme = Theme::default();
    let dir = Path::new(GENERATED_DIR);
    let mut files = vec![
        Generated::css(dir.join("theme.css"), theme_css(&theme)?),
        Generated::ts(dir.join("theme.ts"), theme_ts(&theme)?),
    ];
    files.extend(shader_files(dir)?);
    Ok(files)
}

/// The colors of the theme as CSS custom properties, e.g. `--primary: #020D1A;`.
fn theme_css(theme: &Theme) -> Result<String, Box<dyn Error>> {
    Ok(format!(
        "/* {note} */\n\
         \n\
         /* The colors of the µcad theme. */\n\
         {css}",
        note = note(THEME_SOURCE),
        css = theme.to_css()?
    ))
}

/// The colors of the theme as TypeScript constant `theme`, e.g. `primary: "#020D1A"`.
fn theme_ts(theme: &Theme) -> Result<String, Box<dyn Error>> {
    let toml: toml_edit::DocumentMut = theme.to_toml()?.parse()?;
    let colors: String = toml
        .iter()
        .filter(|(name, _)| *name != "name")
        .filter_map(|(name, item)| Some(format!("  {name}: \"{}\",\n", item.as_str()?)))
        .collect();
    Ok(format!(
        "// {note}\n\
         \n\
         /** The colors of the µcad theme, also as CSS custom properties in `theme.css`. */\n\
         export const theme = {{\n\
         {colors}\
         }} as const;\n",
        note = note(THEME_SOURCE)
    ))
}

/// The shaders of [`WEB_SHADERS`] as TypeScript modules in GLSL ES 3.00 for three.js, e.g.
/// `grid.ts` of `grid_web.wgsl`.
fn shader_files(dir: &Path) -> Result<Vec<Generated>, Box<dyn Error>> {
    WEB_SHADERS
        .iter()
        .map(|shader| {
            let name = shader.name.strip_suffix("_web.wgsl").ok_or(format!(
                "The web shader `{}` without `_web.wgsl`",
                shader.name
            ))?;
            let content = shader_ts(name, shader)?;
            Ok(Generated::ts(dir.join(format!("{name}.ts")), content))
        })
        .collect()
}

/// The default values of a uniform block of a shader, e.g. for the web viewer.
struct UniformDefaults {
    /// The name of the shader, e.g. `model_web.wgsl`.
    shader: &'static str,
    /// The variable of the uniform block in WGSL, e.g. `lighting`.
    block: &'static str,
    /// Where the values come from, e.g. `` `Lighting::default()` ``.
    source: &'static str,
    /// The values, an object with the names of the members of the WGSL struct.
    values: serde_json::Value,
}

/// The default values of uniform blocks of the shaders, e.g. of the lighting of the models.
fn uniform_defaults() -> Result<Vec<UniformDefaults>, Box<dyn Error>> {
    Ok(vec![UniformDefaults {
        shader: ModelWeb::NAME,
        block: "lighting",
        source: "`Lighting::default()`",
        values: serde_json::to_value(Lighting::default())?,
    }])
}

/// `defaults` of `block` as TypeScript object with the floats of its members in the order of
/// their layout, e.g. `{ key: 0.55, … }`, after checking that they have the same members.
fn defaults_ts(defaults: &UniformDefaults, block: &UniformBlock) -> Result<String, Box<dyn Error>> {
    let values = defaults.values.as_object().ok_or(format!(
        "The defaults of `{}` are no struct",
        defaults.block
    ))?;
    let error = |message: &str| format!("The defaults of `{}`: {message}", defaults.block);
    if values.len() != block.members.len() {
        let names: Vec<&String> = values.keys().collect();
        return Err(error(&format!("other members than the WGSL struct: {names:?}")).into());
    }
    let float = |value: &serde_json::Value| -> Result<String, String> {
        let float = value
            .as_f64()
            .ok_or(error(&format!("{value} is no float")))?;
        // The shortest representation of the `f32`, e.g. `0.55`.
        Ok(format!("{:?}", float as f32))
    };
    let members: Vec<String> = block
        .members
        .iter()
        .map(|(name, floats)| {
            let value = values
                .get(name)
                .ok_or(error(&format!("no member `{name}`")))?;
            let floats_ts = match value.as_array() {
                Some(array) if array.len() == *floats as usize => {
                    let array: Vec<String> = array.iter().map(float).collect::<Result<_, _>>()?;
                    format!("[{}]", array.join(", "))
                }
                None if *floats == 1 => float(value)?,
                _ => return Err(error(&format!("`{name}` has not {floats} floats"))),
            };
            Ok(format!("{name}: {floats_ts}"))
        })
        .collect::<Result<_, String>>()?;
    Ok(format!("{{ {} }}", members.join(", ")))
}

/// A TypeScript module of `shader`, which exports the constant `name` with the shaders without
/// `#version`, which three.js writes with `glslVersion: THREE.GLSL3`, with the names of the
/// attributes and of the uniform blocks, which naga generated, and with the default values of
/// uniform blocks of [`uniform_defaults`].
fn shader_ts(name: &str, shader: &ShaderSource) -> Result<String, Box<dyn Error>> {
    let glsl = shader.to_webgl()?;
    // three.js writes `#version 300 es` itself with `glslVersion: THREE.GLSL3`, before its defines.
    let without_version = |glsl: &str| -> Result<String, Box<dyn Error>> {
        let glsl = glsl
            .strip_prefix("#version 300 es\n")
            .ok_or("GLSL without `#version 300 es`")?;
        Ok(glsl.trim_start().to_string())
    };
    let vertex_shader = template_literal(&without_version(&glsl.vertex)?);
    let fragment_shader = template_literal(&without_version(&glsl.fragment)?);
    let attributes: String = glsl
        .attributes
        .iter()
        .map(|(wgsl, glsl)| format!("    {wgsl}: \"{glsl}\",\n"))
        .collect();
    let blocks: String = glsl
        .uniform_blocks
        .iter()
        .map(|(variable, block)| {
            let members: Vec<String> = block
                .members
                .iter()
                .map(|(name, floats)| format!("[\"{name}\", {floats}]"))
                .collect();
            format!(
                "    {variable}: {{ name: \"{}\", members: [{}] }},\n",
                block.name,
                members.join(", ")
            )
        })
        .collect();
    let mut default_sources = Vec::new();
    let mut defaults = String::new();
    for block_defaults in uniform_defaults()?
        .iter()
        .filter(|defaults| defaults.shader == shader.name)
    {
        let block = glsl
            .uniform_blocks
            .get(block_defaults.block)
            .ok_or(format!("No uniform block `{}`", block_defaults.block))?;
        defaults += &format!(
            "    {}: {},\n",
            block_defaults.block,
            defaults_ts(block_defaults, block)?
        );
        default_sources.push(block_defaults.source);
    }
    let defaults = if defaults.is_empty() {
        "{}".to_string()
    } else {
        format!("{{\n{defaults}  }}")
    };
    // E.g. `` `grid_web.wgsl` and `grid.wgsl` ``.
    let sources: Vec<String> = std::iter::once(shader)
        .chain(shader.imports)
        .map(|shader| format!("`{}`", shader.name))
        .chain(default_sources.into_iter().map(str::to_string))
        .collect();
    let sources = match sources.split_last() {
        Some((last, [])) => last.clone(),
        Some((last, others)) => format!("{} and {last}", others.join(", ")),
        None => String::new(),
    };
    Ok(format!(
        "// {note}\n\
         \n\
         /**\n \
          * The shader `{shader_name}` in GLSL ES 3.00 for WebGL2, without `#version`, which three.js\n \
          * writes with `glslVersion: THREE.GLSL3`.\n \
          */\n\
         export const {name} = {{\n\
         \x20 vertexShader: {vertex_shader},\n\
         \x20 fragmentShader: {fragment_shader},\n\
         \x20 /** The names of the vertex attributes in GLSL by their names in WGSL. */\n\
         \x20 attributes: {{\n\
         {attributes}\
         \x20 }},\n\
         \x20 /**\n\
         \x20  * The uniform blocks by the names of their variables in WGSL, with the names and the numbers\n\
         \x20  * of floats of the members in the order of their std140 layout, e.g. for\n\
         \x20  * `THREE.UniformsGroup`.\n\
         \x20  */\n\
         \x20 uniformBlocks: {{\n\
         {blocks}\
         \x20 }},\n\
         \x20 /** The default values of uniform blocks by the names of their members. */\n\
         \x20 defaults: {defaults},\n\
         }} as const;\n",
        note = note(&format!("{sources} of `mucad-viewer-utils`")),
        shader_name = shader.name,
    ))
}

/// `text` as TypeScript template literal, e.g. for multiline GLSL.
fn template_literal(text: &str) -> String {
    let escaped = text
        .replace('\\', "\\\\")
        .replace('`', "\\`")
        .replace("${", "\\${");
    format!("`{escaped}`")
}
